// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 actorBalance = c.getBalance(actor);
        uint256 zeroBalance = c.getBalance(address(0));
        assertTrue(actorBalance == amount && zeroBalance == 0);
    }
}
